<script setup lang="ts">
import { onMounted, ref } from 'vue';import dayjs from 'dayjs';import { http } from '../api/http';import type { Booking } from '../types';import StatusTag from '../components/StatusTag.vue';const date=ref(new Date());const bookings=ref<Booking[]>([]);async function load(){bookings.value=(await http.get('/calendar')).data}function dayItems(value:Date){const key=dayjs(value).format('YYYY-MM-DD');return bookings.value.filter(b=>dayjs(b.startTime).format('YYYY-MM-DD')===key)}onMounted(load);
</script>
<template><div class="page"><div class="page-header"><div><h2>预约日历</h2><p>按日期查看有效会议安排与会议室占用情况</p></div></div><section class="panel calendar-panel"><el-calendar v-model="date"><template #date-cell="{data}"><div class="date-cell"><b>{{data.day.split('-')[2]}}</b><div v-for="item in dayItems(data.date).slice(0,3)" :key="item.id" class="event" :class="item.status.toLowerCase()"><span>{{dayjs(item.startTime).format('HH:mm')}}</span>{{item.title}}</div><small v-if="dayItems(data.date).length>3">还有 {{dayItems(data.date).length-3}} 项</small></div></template></el-calendar><aside><h3>当日安排</h3><div v-if="!dayItems(date).length" class="empty-block">当日暂无会议</div><article v-for="item in dayItems(date)" :key="item.id"><div><strong>{{item.title}}</strong><small>{{item.room.name}} · {{dayjs(item.startTime).format('HH:mm')}}-{{dayjs(item.endTime).format('HH:mm')}}</small></div><StatusTag :status="item.status"/></article></aside></section></div></template>
<style scoped>.calendar-panel{display:grid;grid-template-columns:1fr 300px;padding:0;overflow:hidden}.calendar-panel aside{border-left:1px solid #e9edf3;padding:22px}.calendar-panel aside h3{margin:0 0 18px}.calendar-panel article{display:flex;justify-content:space-between;gap:10px;padding:14px 0;border-bottom:1px solid #eef1f5}.calendar-panel article small{display:block;color:#8994a5;margin-top:6px}.date-cell{height:100%;overflow:hidden}.date-cell>b{font-size:12px}.event{overflow:hidden;white-space:nowrap;text-overflow:ellipsis;margin-top:4px;border-radius:4px;padding:3px 5px;background:#eaf2ff;color:#315f9e;font-size:10px}.event span{margin-right:4px;font-weight:700}.event.completed{background:#edf7f3;color:#397a61}.event.pending{background:#fff5e4;color:#9b6912}.date-cell>small{color:#8c97a8;font-size:9px}</style>
